(248, 1, '2025-09-18 07:29:35', '0000-00-00 00:00:00', 'add_action(\'admin_init\', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === \'edit-comments.php\') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});', 'Completely Disable Comments', '', 'draft', 'closed', 'closed', '', '', '', '', '2025-09-18 07:29:35', '0000-00-00 00:00:00', '', 0, 'http://localhost/ekart/?post_type=wpcode&p=248', 0, 'wpcode', '', 0),
(249, 1, '2025-09-18 14:20:05', '0000-00-00 00:00:00', '/**\r\n * Convert Uploaded Images to WebP Format\r\n *\r\n * This snippet automatically converts JPEG, PNG, and GIF images \r\n * to WebP format during the upload process.\r\n */\r\n\r\nadd_filter(\'wp_handle_upload\', \'wpturbo_handle_upload_convert_to_webp\');\r\nfunction wpturbo_handle_upload_convert_to_webp($upload) {\r\n    if (in_array($upload[\'type\'], [\'image/jpeg\', \'image/png\', \'image/gif\'])) {\r\n        $file_path = $upload[\'file\'];\r\n        if (extension_loaded(\'imagick\') || extension_loaded(\'gd\')) {\r\n            $image_editor = wp_get_image_editor($file_path);\r\n            if (!is_wp_error($image_editor)) {\r\n                $file_info = pathinfo($file_path);\r\n                $dirname = $file_info[\'dirname\'];\r\n                $filename = $file_info[\'filename\'];\r\n                $def_filename = wp_unique_filename($dirname, $filename . \'.webp\');\r\n                $new_file_path = $dirname . \'/\' . $def_filename;\r\n                $saved_image = $image_editor->save($new_file_path, \'image/webp\');\r\n                if (!is_wp_error($saved_image) && file_exists($saved_image[\'path\'])) {\r\n                    // Update the upload data to use the WebP image\r\n                    $upload[\'file\'] = $saved_image[\'path\'];\r\n                    $upload[\'url\'] = str_replace(basename($upload[\'url\']), basename($saved_image[\'path\']), $upload[\'url\']);\r\n                    $upload[\'type\'] = \'image/webp\';\r\n\r\n                    // Optionally delete the original file\r\n                    @unlink($file_path);\r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n    return $upload;\r\n}', 'Convert to WebP', '', 'draft', 'closed', 'closed', '', '', '', '', '2025-09-18 14:20:05', '2025-09-18 14:20:05', '', 0, 'http://localhost/ekart/?post_type=wpcode&#038;p=249', 0, 'wpcode', '', 0),
